import { reserve } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g4-2/bot.mjs";
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { spawn } from "node:child_process";
import assert from "node:assert/strict";

const H = 3600_000;
const T0 = new Date("2026-10-23T10:00:00Z");
const at = (ms) => new Date(T0.getTime() + ms);
const base = await mkdtemp(path.join(tmpdir(), "gate-"));
process.env.STATE_DIR = path.join(base, "nested", "state");

// 1. five allowed across mixed channels, sixth blocked, retryAt = oldest + 24h
const chans = ["sms", "push", "chat", "sms", "push"];
for (let i = 0; i < 5; i++) {
  const r = await reserve("u1", chans[i], at(i * H));
  assert.equal(r.allowed, true); assert.equal(r.retryAt, null);
}
let r = await reserve("u1", "chat", at(6 * H));
assert.equal(r.allowed, false);
assert.equal(r.retryAt.getTime(), T0.getTime() + 24 * H);
assert.match(r.reason, /all channels combined/);
// blocked calls must not count: repeat denial, still same retryAt
r = await reserve("u1", "sms", at(7 * H));
assert.equal(r.allowed, false); assert.equal(r.retryAt.getTime(), T0.getTime() + 24 * H);

// 2. retryAt is exact: 1ms before fails, at retryAt succeeds
r = await reserve("u1", "push", new Date(T0.getTime() + 24 * H - 1));
assert.equal(r.allowed, false);
r = await reserve("u1", "push", r.retryAt === null ? at(0) : new Date(T0.getTime() + 24 * H));
assert.equal(r.allowed, true);

// 3. isolation: other customer unaffected
r = await reserve("u2", "sms", at(6 * H)); assert.equal(r.allowed, true);

// 4. retryAt with ties and multiple expiries: u3 sends at 0,0,0,0,0 then 1h,2h
for (let i = 0; i < 5; i++) assert.equal((await reserve("u3", "sms", T0)).allowed, true);
r = await reserve("u3", "sms", at(1 * H)); assert.equal(r.allowed, false);
assert.equal(r.retryAt.getTime(), T0.getTime() + 24 * H);
r = await reserve("u3", "sms", at(24 * H)); assert.equal(r.allowed, true);
r = await reserve("u3", "sms", at(24 * H)); assert.equal(r.allowed, false);
assert.equal(r.retryAt.getTime(), T0.getTime() + 24 * H + 0); // 5 in window: 0h..? check below
console.log("u3 second retryAt", r.retryAt.toISOString());

// 5. persistence across a fresh process
const child = spawn(process.execPath, ["--input-type=module", "-e",
  `import("${"<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g4-2/bot.mjs"}").then(async m=>{const r=await m.reserve("u1","sms",new Date("${at(8 * H).toISOString()}"));console.log(JSON.stringify(r));})`],
  { env: process.env, stdio: ["ignore", "pipe", "inherit"] });
let out = ""; for await (const c of child.stdout) out += c;
assert.equal(JSON.parse(out).allowed, false);

// 6. race: 12 processes, same customer, same instant, limit 5 -> exactly 5 allowed
const script = `import("${"<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g4-2/bot.mjs"}").then(async m=>{const r=await m.reserve("race","chat",new Date("${T0.toISOString()}"));process.stdout.write(r.allowed?"Y":"N");})`;
const procs = Array.from({ length: 12 }, () => new Promise((res, rej) => {
  const p = spawn(process.execPath, ["--input-type=module", "-e", script], { env: process.env, stdio: ["ignore", "pipe", "inherit"] });
  let o = ""; p.stdout.on("data", (d) => (o += d)); p.on("exit", (c) => (c === 0 ? res(o) : rej(new Error("exit " + c))));
}));
const results = await Promise.all(procs);
assert.equal(results.filter((x) => x === "Y").length, 5, results.join(","));

// 7. race with same customer across 40 in-process concurrent calls
const many = await Promise.all(Array.from({ length: 40 }, (_, i) => reserve("race2", ["sms","push","chat"][i % 3], at(i))));
assert.equal(many.filter((x) => x.allowed).length, 5);

// 8. stale lock from a dead process is recovered
const { mkdir, utimes } = await import("node:fs/promises");
const { createHash } = await import("node:crypto");
const key = createHash("sha256").update("stale").digest("hex");
await mkdir(path.join(process.env.STATE_DIR, "locks"), { recursive: true });
await mkdir(path.join(process.env.STATE_DIR, "locks", `${key}.lock`));
const old = new Date(Date.now() - 60_000); await utimes(path.join(process.env.STATE_DIR, "locks", `${key}.lock`), old, old);
assert.equal((await reserve("stale", "sms", T0)).allowed, true);

console.log("ALL CHECKS PASSED");
EOF
cd /tmp/gate-test && node test.mjs
